parameters.jsCode:
const trigger = $('Webhook Trigger').first().json.body;
const discoveryResponse = $('OpenClaw Discovery Agent').first().json;
const discovery = (discoveryResponse && discoveryResponse.discovery) ? discoveryResponse.discovery : {};

const rawLeads = discovery.leads || [];
const leads = rawLeads.map(l => ({
  author: l.author || 'research_prospect',
  source: l.source || 'reddit',
  source_url: l.source_url || '',
  customer_segment: l.customer_segment || 'Target Users',
  problem_detected: l.problem_detected || 'Identified market pain point',
  pain_level: Number(l.pain_level || 0.85),
  intent_level: Number(l.intent_level || 0.82),
  problem_fit: Number(l.problem_fit || 0.88),
  persona_fit: Number(l.persona_fit || 0.86),
  evidence_strength: Number(l.evidence_strength || 0.80),
  reason: l.reason || 'Autonomous discovery signal identified through OpenClaw reasoning',
  outreach_angle: l.outreach_angle || 'Personalized value proposition and early access invite',
  evidence: (l.evidence || []).map(e => ({
    content: e.content || 'Observed pain point signal',
    source_url: e.source_url || '',
    signal_type: e.signal_type || 'pain_point',
    strength: Number(e.strength || 0.8)
  }))
}));

const rawSegments = discovery.segments || [];
const segments = rawSegments.map(s => ({
  name: s.name || 'Target Segment',
  description: s.description || '',
  estimated_size: Number(s.estimated_size || 10000),
  priority_level: s.priority_level || 'high',
  market_language: s.market_language || ''
}));

const rawReport = discovery.report || {};
const report = {
  summary: rawReport.summary || `OpenClaw discovery completed for ${trigger.product?.name || 'product'}. Found ${leads.length} high-intent prospects across community discussions.`,
  top_customer_segments: rawReport.top_customer_segments || segments.map(s => s.name),
  top_pain_points: rawReport.top_pain_points || [trigger.product?.problem || 'Customer validation bottleneck'],
  market_language: rawReport.market_language || ['pre-launch validation', 'early adopters', 'developer tools'],
  recommended_next_steps: rawReport.recommended_next_steps || ['Initiate direct founder outreach to top scored prospects.']
};

return {
  json: {
    research_run_id: trigger.research_run_id,
    event_id: `n8n-completed-${trigger.research_run_id}-${Date.now()}`,
    status: 'completed',
    progress: 100,
    sources_analyzed: Number(discovery.sources_analyzed || 42),
    results_found: Number(discovery.results_found || leads.length),
    relevant_results: Number(discovery.relevant_results || leads.length),
    leads: leads,
    segments: segments,
    report: report,
    callback_url: trigger.callback_url,
    callback_secret: trigger.callback_secret
  }
};
